import pandas as pd
from random import randint, seed

def task_func(dictionary, item, sample_size=None, random_seed=None):
    df = pd.DataFrame(dictionary)

    positions = []
    item_is_na = pd.isna(item)

    for col_name in df.columns:
        for row_index, value in df[col_name].items():
            if item_is_na:
                if pd.isna(value):
                    positions.append((row_index, col_name))
            elif value == item:
                positions.append((row_index, col_name))

    if sample_size is not None:
        if random_seed is not None:
            seed(random_seed)

        if sample_size <= 0:
            positions = []
        elif sample_size < len(positions):
            pool = positions.copy()
            sampled = []
            for _ in range(sample_size):
                idx = randint(0, len(pool) - 1)
                sampled.append(pool.pop(idx))
            positions = sampled

    return positions, df
